INSERT INTO questions (job_role_id, question_text, category, difficulty, expected_topics, option_a, option_b, option_c, option_d, correct_option, explanation, question_type, active) VALUES
(1, 'Which of the following collections in Java allows concurrent lock-free reads and segmented/bucket-level writes?', 'Collections', 'INTERMEDIATE', 'ConcurrentHashMap, Collections', 'Hashtable', 'Collections.synchronizedMap', 'ConcurrentHashMap', 'TreeMap', 'C', 'ConcurrentHashMap allows concurrent lock-free read operations and achieves thread-safe writes using CAS operations and synchronized bucket nodes.', 'MCQ', TRUE),
(1, 'In Java memory management, where are local primitive variables stored?', 'JVM Internals', 'BEGINNER', 'Stack, JVM, Memory', 'Heap Memory', 'Stack Memory', 'Metaspace', 'Code Cache', 'B', 'Local primitive variables and method call frames are allocated directly on the thread Stack memory.', 'MCQ', TRUE),
(1, 'What is the default initial capacity and load factor of a standard Java HashMap?', 'Core Java', 'BEGINNER', 'HashMap, Capacity, Load Factor', '16 and 0.75', '10 and 0.50', '32 and 0.80', '8 and 0.75', 'A', 'A standard Java HashMap has a default initial capacity of 16 and a default load factor of 0.75.', 'MCQ', TRUE),
(1, 'Which garbage collector in Java 21 is designed for ultra-low latency with pause times under a millisecond?', 'JVM Internals', 'ADVANCED', 'ZGC, Garbage Collection, Java 21', 'Parallel GC', 'CMS (Concurrent Mark Sweep)', 'ZGC (Z Garbage Collector)', 'Serial GC', 'C', 'ZGC (Z Garbage Collector) is a scalable, low-latency garbage collector capable of handling heaps up to multi-terabytes with pause times under 1ms.', 'MCQ', TRUE),
(1, 'Which annotation in Spring Boot is used to mark a class as a service component in the business layer?', 'Spring Boot', 'BEGINNER', 'Annotations, Spring Service', '@Repository', '@Service', '@Controller', '@Configuration', 'B', '@Service is a specialization of @Component used to annotate classes that perform business logic.', 'MCQ', TRUE),
(1, 'What happens if two unequal objects return the exact same hashCode in Java?', 'Core Java', 'INTERMEDIATE', 'HashCode, Hash Collision, HashMap', 'A runtime collision exception is thrown', 'They are stored in the same bucket and compared using equals()', 'The second object replaces the first in the HashMap', 'The JVM terminates execution', 'B', 'When two distinct objects produce the same hashCode, a hash collision occurs; they are placed in the same bucket and resolved using equals().', 'MCQ', TRUE),
(1, 'In modern Java (Java 14+), what is the primary benefit of declaring a Record?', 'Modern Java', 'BEGINNER', 'Java Records, Immutability', 'Allows mutable public fields without getters', 'Creates a transparent, immutable data carrier with canonical constructor, equals(), and hashCode()', 'Inherits from multiple concrete classes', 'Enables dynamic method dispatching at runtime', 'B', 'Records are immutable data carriers that eliminate boilerplate by automatically generating equals, hashCode, toString, and accessor methods.', 'MCQ', TRUE),
(1, 'What is the difference between fail-fast and fail-safe iterators in Java?', 'Collections', 'INTERMEDIATE', 'Iterators, ConcurrentModificationException', 'Fail-fast throws ConcurrentModificationException on concurrent modification; fail-safe operates on a clone', 'Fail-safe throws ConcurrentModificationException immediately; fail-fast does not', 'Both behave identically in single-threaded environments', 'Fail-fast only works with arrays', 'A', 'Fail-fast iterators (e.g. ArrayList) fail immediately when modified structurally during iteration; fail-safe iterators work on a snapshot copy.', 'MCQ', TRUE),
(1, 'Which CompletableFuture method is used to transform the result of a stage asynchronously without blocking?', 'Concurrency', 'ADVANCED', 'CompletableFuture, Asynchronous', 'get()', 'join()', 'thenApplyAsync()', 'await()', 'C', 'thenApplyAsync() transforms the result of the previous completion stage asynchronously on a ForkJoinPool thread.', 'MCQ', TRUE),
(1, 'In Spring Data JPA, what does the @Transactional(readOnly = true) attribute achieve?', 'Spring JPA', 'INTERMEDIATE', 'Transactional, Hibernate, Performance', 'Locks the database table against any queries', 'Allows Hibernate to skip dirty checking on entities, optimizing memory and throughput', 'Disables all database read operations', 'Drops the current connection immediately', 'B', 'When readOnly=true is specified, Hibernate optimizes performance by skipping dirty checking and transaction flush operations.', 'MCQ', TRUE),
(1, 'What does the volatile keyword guarantee in Java multi-threading?', 'Concurrency', 'INTERMEDIATE', 'Volatile, Visibility, JMM', 'Atomicity of compound operations (e.g., count++)', 'Visibility of writes across CPU caches and prevents instruction reordering', 'Acquisition of an exclusive monitor lock on the object', 'Prevention of garbage collection on that variable', 'B', 'volatile ensures changes written by one thread are immediately visible to all other threads and establishes a happens-before memory relationship.', 'MCQ', TRUE),
(1, 'Which Java 21 feature introduces lightweight threads managed by the Java Virtual Machine rather than the underlying OS?', 'Modern Java', 'ADVANCED', 'Virtual Threads, Project Loom, Java 21', 'Fibers', 'Virtual Threads (Project Loom)', 'Green Threads', 'Executor Threads', 'B', 'Virtual Threads (introduced as a standard feature in Java 21) are lightweight user-mode threads managed by the JVM that reduce the cost of high-throughput I/O.', 'MCQ', TRUE),
(1, 'What is the purpose of Spring Boot Actuator in production microservices?', 'Spring Boot', 'BEGINNER', 'Actuator, Observability, Health', 'Generates frontend UI views automatically', 'Exposes health, metrics, environment, and diagnostic endpoints for monitoring', 'Manages database backups', 'Encrypts incoming HTTP payloads', 'B', 'Spring Boot Actuator provides built-in production-ready features such as health checks, audit metrics, and monitoring endpoints.', 'MCQ', TRUE),
(1, 'What is the default bean scope in the Spring ApplicationContext?', 'Spring Framework', 'BEGINNER', 'Spring Bean, Scope, Singleton', 'Prototype', 'Singleton', 'Request', 'Session', 'B', 'The default scope for all Spring beans is Singleton, meaning a single shared instance is maintained in the container.', 'MCQ', TRUE),
(1, 'How does the Java ForkJoinPool framework execute compute-intensive recursive tasks efficiently?', 'Concurrency', 'ADVANCED', 'ForkJoinPool, Work Stealing', 'By locking all CPUs until a task finishes', 'Using a work-stealing algorithm where idle worker threads steal tasks from busy queues', 'By creating a new operating system thread for each recursive call', 'By serializing tasks to the disk cache', 'B', 'ForkJoinPool uses work-stealing: worker threads that run out of work look into the deques of other threads and steal pending subtasks.', 'MCQ', TRUE),
(1, 'What is the time complexity of searching for an element in a balanced Java TreeMap?', 'Data Structures', 'INTERMEDIATE', 'TreeMap, Red-Black Tree, Big-O', 'O(1)', 'O(log N)', 'O(N)', 'O(N log N)', 'B', 'Java TreeMap is backed by a Red-Black Tree, guaranteeing O(log N) time cost for containsKey, get, put, and remove operations.', 'MCQ', TRUE),
(1, 'Which HTTP method should be used when updating only specific fields of an existing resource in a RESTful API?', 'REST API', 'BEGINNER', 'REST, HTTP Methods, PATCH', 'PUT', 'PATCH', 'POST', 'DELETE', 'B', 'PATCH is specifically used for partial resource modification, whereas PUT is intended for complete resource replacement.', 'MCQ', TRUE),
(1, 'What problem does the N+1 select issue represent in Hibernate/JPA?', 'Hibernate', 'INTERMEDIATE', 'Hibernate, N+1, FetchType', 'Executing 1 query to fetch parent records and then N subsequent queries for associated children', 'A deadlock when 2 transactions query at the same instant', 'Exceeding the maximum allowed database connection pool limit', 'Having N+1 entity tables in a single database schema', 'A', 'The N+1 problem occurs when fetching N parent entities results in 1 query for parents plus N separate queries to fetch each parent child collection.', 'MCQ', TRUE),
(1, 'How do you solve the N+1 select problem in Spring Data JPA?', 'Hibernate', 'INTERMEDIATE', 'JPA, JOIN FETCH, EntityGraph', 'By setting FetchType to EAGER everywhere', 'Using JOIN FETCH queries or @EntityGraph', 'By disabling Hibernate caching', 'By increasing the database connection pool size', 'B', 'JOIN FETCH queries and @EntityGraph instruct Hibernate to fetch the parent and child entities together in a single unified SQL JOIN.', 'MCQ', TRUE),
(1, 'What is the difference between checked and unchecked exceptions in Java?', 'Core Java', 'BEGINNER', 'Exceptions, RuntimeException', 'Checked exceptions inherit from RuntimeException; unchecked do not', 'Checked exceptions are verified at compile-time; unchecked exceptions (RuntimeException) are not', 'Unchecked exceptions must be declared in the throws clause', 'Checked exceptions crash the JVM immediately', 'B', 'Checked exceptions (subclasses of Exception excluding RuntimeException) are checked at compile time and must be handled or declared.', 'MCQ', TRUE),
(1, 'Which design pattern is primarily used by Spring Boot to implement dependency injection?', 'Design Patterns', 'INTERMEDIATE', 'Inversion of Control, Dependency Injection', 'Factory Method', 'Inversion of Control (IoC) / Dependency Injection', 'Observer Pattern', 'Singleton Pattern', 'B', 'Spring uses Inversion of Control (IoC), injecting collaborators into dependent objects rather than allowing objects to instantiate them directly.', 'MCQ', TRUE);
INSERT INTO questions (job_role_id, question_text, category, difficulty, expected_topics, option_a, option_b, option_c, option_d, correct_option, explanation, question_type, active) VALUES
(2, 'What is the Global Interpreter Lock (GIL) in CPython?', 'Python Internals', 'INTERMEDIATE', 'GIL, CPython, Threading', 'A lock preventing garbage collection', 'A mutex that prevents multiple native threads from executing Python bytecodes simultaneously', 'A compiler optimization for faster loops', 'A network socket security protocol in Python', 'B', 'The GIL in CPython is a mutual exclusion lock that ensures only one native thread runs Python bytecode at a time.', 'MCQ', TRUE),
(2, 'What is the difference between a Python list and a tuple?', 'Core Python', 'BEGINNER', 'List, Tuple, Mutability', 'Lists are immutable; tuples are mutable', 'Lists are mutable; tuples are immutable and hashable', 'Tuples consume more memory than lists of identical length', 'Lists cannot store heterogeneous data types', 'B', 'Lists are mutable dynamic arrays, whereas tuples are fixed-size immutable sequences that can be used as dictionary keys when their contents are hashable.', 'MCQ', TRUE),
(2, 'What does the yield keyword do when placed inside a Python function?', 'Core Python', 'BEGINNER', 'Generators, Yield, Iterators', 'Terminates the program execution', 'Turns the function into a generator that produces values lazily one at a time', 'Imports external C libraries', 'Forces immediate memory allocation of all elements', 'B', 'yield transforms a function into a generator iterator, pausing execution and returning a value while maintaining state for subsequent next() calls.', 'MCQ', TRUE),
(2, 'How does Python handle memory management and cleanup of unreferenced objects?', 'Python Internals', 'INTERMEDIATE', 'Garbage Collection, Reference Counting', 'Manual deallocation like C free()', 'Reference counting combined with a cyclic garbage collector', 'Mark and sweep only', 'Stack unwinding exclusively', 'B', 'CPython relies primarily on reference counting for immediate cleanup, augmented by a generational cyclic GC for circular references.', 'MCQ', TRUE),
(2, 'In Python, what is the output of isinstance(True, int)?', 'Core Python', 'BEGINNER', 'Data Types, Boolean, Integers', 'False', 'True', 'TypeError', 'None', 'B', 'In Python, bool is a direct subclass of int, so True is an instance of int (with integer value 1).', 'MCQ', TRUE),
(2, 'What is the difference between *args and **kwargs in Python function definitions?', 'Functions', 'BEGINNER', 'Function Arguments, args, kwargs', '*args passes keyword arguments; **kwargs passes positional tuples', '*args collects arbitrary positional arguments as a tuple; **kwargs collects keyword arguments as a dict', '*args is only allowed in class methods', 'There is no difference; they are interchangeable', 'B', '*args packs extra positional arguments into a tuple, while **kwargs packs extra named keyword arguments into a dictionary.', 'MCQ', TRUE),
(2, 'Which built-in Python module is standard for writing asynchronous coroutines and concurrent I/O operations?', 'Async IO', 'INTERMEDIATE', 'asyncio, Coroutines', 'threading', 'multiprocessing', 'asyncio', 'concurrent.futures', 'C', 'asyncio is Python standard library for writing concurrent code using the async/await syntax and event loop.', 'MCQ', TRUE),
(2, 'What is the purpose of the @functools.wraps decorator when authoring custom Python decorators?', 'Decorators', 'INTERMEDIATE', 'Decorators, Functools, Wraps', 'Compiles the function into native C code', 'Preserves the original function name, docstring, and metadata', 'Enforces strict type checking on parameters', 'Makes the decorated function asynchronous', 'B', '@functools.wraps copies the original function name, docstring, annotations, and module attributes to the wrapper function.', 'MCQ', TRUE),
(2, 'What is the time complexity of looking up a key in a Python dictionary with no collisions?', 'Data Structures', 'BEGINNER', 'Dictionary, Hash Table, Time Complexity', 'O(1)', 'O(log N)', 'O(N)', 'O(N^2)', 'A', 'Python dictionaries are implemented as highly optimized hash tables offering O(1) average time complexity for lookups, insertions, and deletions.', 'MCQ', TRUE),
(2, 'In Python OOP, what is the method resolution order (MRO) algorithm used in modern Python 3?', 'OOP', 'ADVANCED', 'MRO, C3 Linearization, Inheritance', 'Depth-First Search (DFS)', 'Breadth-First Search (BFS)', 'C3 Linearization', 'Round Robin', 'C', 'Python uses the C3 Linearization algorithm to determine the Method Resolution Order (MRO) in multiple inheritance hierarchies.', 'MCQ', TRUE),
(2, 'What does the with statement (Context Manager) guarantee in Python?', 'Core Python', 'BEGINNER', 'Context Managers, with statement', 'Code executes in parallel threads', 'Resource acquisition and cleanup (like closing files/sockets) even if exceptions occur', 'Variables inside the block have local scope only', 'Disables garbage collection inside the block', 'B', 'The with statement binds the execution of a block to methods defined by a context manager (__enter__ and __exit__), guaranteeing cleanup.', 'MCQ', TRUE),
(2, 'What is the difference between deepcopy and shallow copy in Python copy module?', 'Core Python', 'INTERMEDIATE', 'Copy, Shallow vs Deep', 'Shallow copy duplicates nested objects; deepcopy duplicates only references', 'Shallow copy constructs a new object with references to child objects; deepcopy recursively duplicates all child objects', 'They perform the exact same operation', 'deepcopy only works on primitive integers', 'B', 'Shallow copy creates a new compound object and inserts references to existing items; deepcopy recursively copies all objects found.', 'MCQ', TRUE),
(2, 'In FastAPI, what library is used under the hood for robust data validation and serialization?', 'FastAPI', 'BEGINNER', 'FastAPI, Pydantic, Validation', 'Marshmallow', 'Pydantic', 'Cerberus', 'Django Forms', 'B', 'FastAPI is built on top of Pydantic for schema definition, request body parsing, automatic data validation, and serialization.', 'MCQ', TRUE),
(2, 'How do you achieve true CPU-bound parallelism across multiple processor cores in Python despite the GIL?', 'Concurrency', 'INTERMEDIATE', 'Multiprocessing, CPU Bound, GIL', 'By using standard threading.Thread', 'By using the multiprocessing module or ProcessPoolExecutor', 'By using asyncio.gather', 'By increasing the thread stack size', 'B', 'The multiprocessing module bypasses the GIL by spawning separate OS processes, each with its own independent Python interpreter and GIL.', 'MCQ', TRUE),
(2, 'What is a Python lambda function?', 'Core Python', 'BEGINNER', 'Lambda, Anonymous Functions', 'A recursive function that cannot return a value', 'A small anonymous function defined with the lambda keyword containing a single expression', 'A function that only accepts string arguments', 'A method bound strictly to a class instance', 'B', 'A lambda function is an anonymous inline function restricted to a single expression whose evaluated result is automatically returned.', 'MCQ', TRUE),
(2, 'In Python, what does the __slots__ declaration in a class accomplish?', 'Python Internals', 'ADVANCED', 'Slots, Memory Optimization', 'Allows unlimited dynamic attributes to be added at runtime', 'Restricts allowed attributes to a fixed set and saves memory by preventing creation of instance __dict__', 'Makes all class methods private', 'Forces the class to be serialized as JSON', 'B', '__slots__ avoids the memory overhead of a per-instance __dict__ dictionary, yielding significant memory savings across millions of instances.', 'MCQ', TRUE),
(2, 'What is the difference between is and == in Python?', 'Core Python', 'BEGINNER', 'Equality, Identity, Operators', 'is checks value equality; == checks object identity (memory address)', '== checks value equality; is checks object identity (same memory address)', 'They are completely synonymous', '== is only used for mathematical numbers', 'B', '== tests whether the values of the operands are equal; is tests whether both variables refer to the exact same object in memory.', 'MCQ', TRUE),
(2, 'What does the asyncio.gather() function do in Python?', 'Async IO', 'INTERMEDIATE', 'asyncio, Gather, Concurrency', 'Terminates all running coroutines immediately', 'Runs multiple awaitable objects concurrently and aggregates their results into a list', 'Converts async code into synchronous blocking code', 'Profiles memory consumption of coroutines', 'B', 'asyncio.gather(*aws) schedules multiple awaitable tasks or coroutines concurrently in the event loop and returns their results in order.', 'MCQ', TRUE),
(2, 'In Python, what is the purpose of the __init__.py file inside a directory?', 'Modules & Packages', 'BEGINNER', 'Packages, Modules, Init', 'Contains the application entry point only', 'Marks the directory as a Python package that can be imported', 'Compiles Python scripts into bytecode', 'Configures database connection strings', 'B', '__init__.py indicates to the Python interpreter that the directory should be treated as an importable package namespace.', 'MCQ', TRUE),
(2, 'What is the time complexity of inserting an item at the beginning of a standard Python list (list.insert(0, item))?', 'Data Structures', 'INTERMEDIATE', 'List, Time Complexity, Big-O', 'O(1)', 'O(log N)', 'O(N)', 'O(N log N)', 'B', 'Inserting at index 0 requires shifting all existing elements one position to the right in the underlying contiguous array, taking O(N) time.', 'MCQ', TRUE),
(2, 'Which data structure from the collections module provides O(1) appends and pops from both ends?', 'Collections', 'BEGINNER', 'Deque, Collections, Queue', 'collections.defaultdict', 'collections.OrderedDict', 'collections.deque', 'collections.Counter', 'C', 'collections.deque (double-ended queue) guarantees O(1) time complexity for appending and popping elements from both the left and right ends.', 'MCQ', TRUE);
INSERT INTO questions (job_role_id, question_text, category, difficulty, expected_topics, option_a, option_b, option_c, option_d, correct_option, explanation, question_type, active) VALUES
(3, 'Where should short-lived JWT access tokens and long-lived refresh tokens be stored to mitigate XSS and CSRF risks?', 'Security & Auth', 'INTERMEDIATE', 'JWT, XSS, CSRF, Cookies', 'Both in localStorage', 'Access token in memory/short-lived variable; refresh token in an HttpOnly, Secure, SameSite cookie', 'Both in window.name', 'In URL query parameters', 'B', 'Storing refresh tokens in HttpOnly Secure SameSite cookies prevents client-side script access (mitigating XSS) while SameSite mitigates CSRF.', 'MCQ', TRUE),
(3, 'What is a CORS preflight request and which HTTP method does the browser send?', 'Web Architecture', 'INTERMEDIATE', 'CORS, Preflight, OPTIONS', 'An initial GET request to check server load', 'An OPTIONS request sent by the browser before non-simple cross-origin requests to verify permissions', 'A POST request with dummy payload', 'A HEAD request to inspect headers', 'B', 'Browsers automatically send an HTTP OPTIONS request as a preflight check before non-simple cross-origin requests to check server CORS permissions.', 'MCQ', TRUE),
(3, 'What HTTP status code is most appropriate when a requested resource is created successfully on the server?', 'REST API', 'BEGINNER', 'HTTP Status, 201 Created', '200 OK', '201 Created', '204 No Content', '202 Accepted', 'B', '201 Created indicates that the request succeeded and led to the creation of a new resource.', 'MCQ', TRUE),
(3, 'In React, what is the key difference between props and state?', 'React', 'BEGINNER', 'Props, State, React Core', 'Props are internal and mutable; state is external and read-only', 'Props are passed from parent to child (read-only); state is managed internally within a component', 'State cannot be updated using hooks', 'Props can only store primitive strings', 'B', 'Props are read-only properties passed down from parent components, while state is local and mutable data managed inside the component.', 'MCQ', TRUE),
(3, 'What is the purpose of database connection pooling in a backend application?', 'Database', 'BEGINNER', 'Connection Pool, HikariCP, Performance', 'Encrypts database tables automatically', 'Maintains a reusable pool of open database connections to eliminate TCP handshake overhead per request', 'Converts SQL queries into NoSQL documents', 'Stores database backups in memory', 'B', 'Opening and closing database TCP connections is expensive; a pool maintains active connections ready for reuse, maximizing throughput.', 'MCQ', TRUE),
(3, 'What is idempotency in REST API design?', 'API Design', 'INTERMEDIATE', 'Idempotency, HTTP Methods', 'An API that only accepts JSON payloads', 'Making identical requests multiple times has the exact same side-effect on the server as making it once', 'An API that requires authentication on every route', 'An API that caches all responses in Redis', 'B', 'An idempotent HTTP method (like GET, PUT, DELETE) produces the exact same server resource state regardless of whether it is called once or ten times.', 'MCQ', TRUE),
(3, 'Which of the following HTTP methods is NOT idempotent by definition?', 'REST API', 'BEGINNER', 'Idempotency, POST, HTTP Methods', 'GET', 'PUT', 'DELETE', 'POST', 'D', 'POST is not idempotent; submitting multiple identical POST requests typically creates multiple distinct records or transactions.', 'MCQ', TRUE),
(3, 'In modern frontend bundling, what is tree shaking?', 'Frontend Tooling', 'INTERMEDIATE', 'Tree Shaking, Vite, Webpack', 'Automated code formatting using Prettier', 'The elimination of unused dead code from the final JavaScript production bundle', 'A testing technique for checking UI component trees', 'Converting TypeScript into binary machine code', 'B', 'Tree shaking is a dead-code elimination technique powered by ES module static analysis that discards unexported or unreferenced functions from the build.', 'MCQ', TRUE),
(3, 'What does the ACID property of Atomicity guarantee in database transactions?', 'Databases', 'BEGINNER', 'ACID, Atomicity, Transactions', 'Transactions execute with zero network latency', 'All operations within a transaction succeed completely or all are rolled back with no partial state', 'Data is replicated to at least two physical servers', 'Transactions are executed sequentially without concurrency', 'B', 'Atomicity ensures an all-or-nothing guarantee: if any statement in the transaction fails, the entire transaction is rolled back.', 'MCQ', TRUE),
(3, 'What is the difference between SQL and NoSQL database indexing strategies?', 'Databases', 'INTERMEDIATE', 'B-Tree, LSM-Tree, Databases', 'SQL databases use B-Trees for structured range queries; document stores frequently use B-Trees or inverted indexes for search', 'NoSQL databases do not support any indexes', 'SQL indexes are always kept in memory; NoSQL indexes are stored on tape', 'SQL databases only index primary keys', 'A', 'Relational engines rely heavily on B+ Trees for fast range and equality scans, while NoSQL engines use hash, inverted, or LSM tree indexes.', 'MCQ', TRUE),
(3, 'What is the primary role of a Reverse Proxy like Nginx in a production full stack deployment?', 'DevOps & Architecture', 'INTERMEDIATE', 'Nginx, Reverse Proxy, Load Balancing', 'Compiles backend Java code on the fly', 'Terminates SSL, routes traffic, balances load, and serves static frontend assets', 'Replaces the need for a database', 'Generates unit tests automatically', 'B', 'A reverse proxy sits in front of web applications to handle SSL termination, load balancing, request buffering, compression, and static asset serving.', 'MCQ', TRUE),
(3, 'In React, why must you NOT call Hooks inside loops, conditions, or nested functions?', 'React Hooks', 'INTERMEDIATE', 'React Hooks, Rules of Hooks', 'It reduces browser rendering speed by 50%', 'React relies on the call order of Hooks across re-renders to correctly preserve state', 'JavaScript syntax disallows functions inside loops', 'It causes an immediate memory leak in the browser', 'B', 'React tracks hook state by the sequential call order of hooks; placing them in conditional branches disrupts this order and corrupts component state.', 'MCQ', TRUE),
(3, 'Which CSS layout system is best suited for two-dimensional layouts containing both rows and columns?', 'CSS', 'BEGINNER', 'CSS Grid, Flexbox, Layout', 'CSS Float', 'CSS Flexbox', 'CSS Grid', 'CSS Inline-Block', 'C', 'CSS Grid is designed specifically for two-dimensional grid layouts (rows and columns simultaneously), whereas Flexbox is primarily one-dimensional.', 'MCQ', TRUE),
(3, 'What is the purpose of database database migrations tools like Flyway or Liquibase?', 'DevOps & DB', 'BEGINNER', 'Flyway, Database Migrations, Version Control', 'Exporting database tables to Excel spreadsheets', 'Managing, tracking, and applying version-controlled database schema changes automatically across environments', 'Compressing database backups into ZIP archives', 'Replacing SQL queries with ORM queries', 'B', 'Migration tools version-control database schema scripts and execute migrations deterministically across development, testing, and production.', 'MCQ', TRUE),
(3, 'What is Content Security Policy (CSP) in web security?', 'Security', 'ADVANCED', 'CSP, XSS, Security Headers', 'A legal document outlining website cookies', 'An HTTP response header that restricts the resources (scripts, styles, images) a browser is allowed to load', 'An encryption key for passwords', 'A firewall rule for database servers', 'B', 'CSP is an HTTP header that mitigates Cross-Site Scripting (XSS) and data injection attacks by restricting origins of scripts and resources.', 'MCQ', TRUE),
(3, 'What is the difference between client-side routing (SPA) and traditional server-side routing?', 'Web Architecture', 'BEGINNER', 'SPA, Routing, Client-Side', 'Client-side routing changes views by updating the DOM in JavaScript without a full browser reload; server-side requires a full page fetch', 'Client-side routing is incompatible with React', 'Server-side routing does not support URLs', 'Client-side routing requires downloading an executable program', 'A', 'Single Page Applications (SPAs) intercept URL changes in the browser and swap component views without requesting a full HTML page from the server.', 'MCQ', TRUE),
(3, 'What is the purpose of a Docker Compose file in full stack development?', 'DevOps', 'BEGINNER', 'Docker, Docker Compose, Containers', 'A compiler for C++ code', 'A YAML file that defines and runs multi-container Docker applications with linked networks and volumes', 'A database query optimization tool', 'A CSS preprocessing script', 'B', 'docker-compose.yml defines multi-container applications (e.g. frontend, backend, database), enabling one-command startup of the complete stack.', 'MCQ', TRUE),
(3, 'What is the purpose of an index in a relational database?', 'Databases', 'BEGINNER', 'Indexing, SQL, B-Tree', 'To enforce encryption on column values', 'To provide a fast lookup data structure (e.g. B-Tree) that avoids full table scans during queries', 'To convert text columns to uppercase', 'To delete duplicate rows automatically', 'B', 'Indexes create auxiliary lookup structures that allow the database engine to find specific rows in O(log N) time rather than scanning every table row.', 'MCQ', TRUE),
(3, 'What is the difference between synchronous and asynchronous code execution in JavaScript?', 'JavaScript', 'BEGINNER', 'Async, Event Loop, JavaScript', 'Synchronous blocks thread execution until completion; asynchronous delegates work and continues execution via the Event Loop', 'Asynchronous code is executed on multiple physical CPU threads simultaneously in browser V8', 'Synchronous code can only be run in Node.js', 'Asynchronous code cannot return values', 'A', 'JavaScript is single-threaded; synchronous code blocks the thread, while asynchronous callbacks/promises yield execution to the Event Loop.', 'MCQ', TRUE),
(3, 'What does the HTTP 403 Forbidden status code signify compared to 401 Unauthorized?', 'REST API', 'BEGINNER', 'HTTP 401, HTTP 403, Security', '401 means credentials are valid; 403 means the server is down', '401 means unauthenticated (missing/invalid credentials); 403 means authenticated but lacking necessary permissions', 'They are completely identical and interchangeable', '403 is only returned for file downloads', 'B', '401 Unauthorized indicates unauthenticated access; 403 Forbidden indicates identity is known but authorization is denied.', 'MCQ', TRUE),
(3, 'What is the primary benefit of using TypeScript over vanilla JavaScript in enterprise projects?', 'TypeScript', 'BEGINNER', 'TypeScript, Static Typing', 'TypeScript runs faster in the browser without compilation', 'TypeScript provides compile-time static type checking, early bug detection, and enhanced IDE autocompletion', 'TypeScript eliminates the need for unit testing', 'TypeScript automatically creates database schemas', 'B', 'TypeScript introduces static type checking during development, catching type errors before code reaches production runtime.', 'MCQ', TRUE);
INSERT INTO questions (job_role_id, question_text, category, difficulty, expected_topics, option_a, option_b, option_c, option_d, correct_option, explanation, question_type, active) VALUES
(4, 'What is the primary purpose of the React Virtual DOM?', 'React Core', 'BEGINNER', 'Virtual DOM, Reconciliation, Performance', 'To replace the browser HTML parser entirely', 'To maintain an in-memory representation of the UI and batch DOM updates efficiently using a diffing algorithm', 'To store global variables in local storage', 'To compile JSX directly into WebAssembly', 'B', 'The Virtual DOM keeps an in-memory tree of UI elements, calculating minimal diffs before applying batched updates to the real browser DOM.', 'MCQ', TRUE),
(4, 'In React, what happens when a component re-renders?', 'React Core', 'BEGINNER', 'Re-rendering, Component Lifecycle', 'The entire browser webpage reloads from scratch', 'The component function executes again, generating a new Virtual DOM representation for reconciliation', 'All child components are permanently unmounted', 'The browser cache is cleared', 'B', 'Re-rendering executes the component function with updated props or state, producing a new JSX tree that React compares with the previous tree.', 'MCQ', TRUE),
(4, 'What is the difference between useMemo and useCallback in React?', 'React Hooks', 'INTERMEDIATE', 'useMemo, useCallback, Memoization', 'useMemo memoizes a computed value; useCallback memoizes a function definition', 'useCallback memoizes a value; useMemo memoizes a component', 'useMemo only works with integers; useCallback works with strings', 'They are aliases for the same underlying function', 'A', 'useMemo caches the result of an expensive calculation; useCallback caches the callback function instance between renders to prevent re-creation.', 'MCQ', TRUE),
(4, 'What is the purpose of the key prop when rendering lists of elements in React?', 'React Core', 'BEGINNER', 'Key prop, Reconciliation, Lists', 'Styles the element with CSS', 'Helps React uniquely identify which items have changed, been added, or been removed during reconciliation', 'Stores the element in session storage', 'Binds click events to the DOM node', 'B', 'Unique keys provide stable identities to list elements across renders, preventing unwanted DOM mutations and state mix-ups.', 'MCQ', TRUE),
(4, 'What does the CSS property box-sizing: border-box do?', 'CSS', 'BEGINNER', 'box-sizing, CSS Box Model', 'Excludes padding and border from the element total width and height', 'Includes padding and border within the specified width and height of an element', 'Removes borders from all child elements', 'Centers the element horizontally', 'B', 'With border-box, the width and height properties include content, padding, and border, making responsive layouts much easier to manage.', 'MCQ', TRUE),
(4, 'What are Core Web Vitals, and what does LCP measure?', 'Web Performance', 'ADVANCED', 'Core Web Vitals, LCP, Performance', 'Largest Contentful Paint measures perceived loading speed by timing when the main page content has likely loaded', 'Local Cache Persistence measures disk usage', 'Latency Control Protocol measures WebSocket ping', 'Layout Constraint Processing measures CSS compiler speed', 'A', 'Largest Contentful Paint (LCP) measures how long it takes for the largest visual content element (image, video, text block) in the viewport to render.', 'MCQ', TRUE),
(4, 'In TypeScript, what is the difference between an interface and a type alias?', 'TypeScript', 'INTERMEDIATE', 'TypeScript, Interface, Type', 'Interfaces can be extended via declaration merging; type aliases cannot be merged after declaration', 'Type aliases cannot define object shapes', 'Interfaces can only be used with classes', 'There is zero functional difference', 'A', 'Interfaces support declaration merging (multiple declarations of the same interface combine) and are ideal for public APIs and object contracts.', 'MCQ', TRUE),
(4, 'What is the JavaScript Event Loop microtask queue, and which of the following queues a microtask?', 'JavaScript Internals', 'ADVANCED', 'Event Loop, Microtasks, Promises', 'setTimeout()', 'Promise.then() / queueMicrotask()', 'setInterval()', 'requestAnimationFrame()', 'B', 'Promise resolution handlers (.then/.catch) and queueMicrotask are processed in the microtask queue, which drains before the next macrotask.', 'MCQ', TRUE),
(4, 'In React 18, what is automatic batching?', 'React 18', 'INTERMEDIATE', 'Automatic Batching, React 18', 'Batching git commits automatically', 'React groups multiple state updates into a single re-render, even within promises, timeouts, and native event handlers', 'Batching network requests into one HTTP call', 'Compiling multiple components into one file', 'B', 'React 18 batches all state updates occurring within async operations, promises, or timeouts to eliminate unnecessary intermediate re-renders.', 'MCQ', TRUE),
(4, 'What is a closure in JavaScript?', 'JavaScript', 'INTERMEDIATE', 'Closures, Lexical Scope', 'A function that immediately terminates the browser window', 'A function bundled together with its lexical environment, allowing access to an outer function scope even after it has returned', 'A syntax error when curly braces are unclosed', 'A CSS pseudo-class for closed accordions', 'B', 'A closure gives an inner function access to its outer function scope even after the outer function has completed execution.', 'MCQ', TRUE),
(4, 'What does the useEffect cleanup function do in React?', 'React Hooks', 'BEGINNER', 'useEffect, Cleanup Function, Subscriptions', 'Cleans browser history', 'Runs before the component unmounts or before re-running the effect to unsubscribe or cancel pending requests', 'Resets all component state variables to null', 'Deletes the component source code from memory', 'B', 'The cleanup function returned by useEffect executes before the effect runs again or when the component unmounts, preventing memory leaks.', 'MCQ', TRUE),
(4, 'Which Tailwind CSS class is used to make a flex container align its items along the center of the cross axis?', 'Tailwind CSS', 'BEGINNER', 'Tailwind, Flexbox, Alignment', 'justify-center', 'items-center', 'content-center', 'self-center', 'B', 'In Tailwind CSS, items-center sets align-items: center, centering flex items along the cross axis.', 'MCQ', TRUE),
(4, 'What is the purpose of React.lazy() and Suspense?', 'React Core', 'INTERMEDIATE', 'Code Splitting, Lazy Loading, Suspense', 'To delay rendering for 5 seconds deliberately', 'To enable dynamic code-splitting by lazily loading components only when they are rendered, displaying a fallback UI meanwhile', 'To catch JavaScript runtime exceptions', 'To cache API responses in indexedDB', 'B', 'React.lazy lets you render a dynamic import as a regular component, and Suspense coordinates displaying a fallback spinner while the chunk loads.', 'MCQ', TRUE),
(4, 'What is the difference between localStorage and sessionStorage in the browser?', 'Browser Storage', 'BEGINNER', 'Storage, localStorage, sessionStorage', 'localStorage data persists across browser sessions; sessionStorage data is cleared when the browser tab closes', 'sessionStorage data is stored on the server; localStorage is stored in memory', 'localStorage has a 5KB limit; sessionStorage has a 50MB limit', 'localStorage only stores binary images', 'A', 'localStorage persists indefinitely until cleared programmatically or by the user; sessionStorage expires as soon as the tab or window is closed.', 'MCQ', TRUE),
(4, 'What does the debounce technique achieve in frontend search inputs?', 'Web Performance', 'INTERMEDIATE', 'Debounce, Event Handling, Performance', 'Runs the search query immediately on every single keystroke', 'Delays function execution until a specified idle duration has passed without new keystrokes, reducing API calls', 'Encrypts the input text before sending', 'Disables the input field permanently', 'B', 'Debouncing limits the rate at which a function fires by waiting for a quiet period after the last event before executing the handler.', 'MCQ', TRUE),
(4, 'In modern CSS, what is the purpose of the rem unit?', 'CSS', 'BEGINNER', 'CSS Units, rem, Responsive Design', 'Relative to the viewport width', 'Relative to the root (html) element font-size', 'Relative to the parent element font-size', 'Absolute measurement equal to exactly 16 pixels always', 'B', 'rem stands for Root EM: it is calculated relative to the font-size of the root <html> element (which defaults to 16px in most browsers).', 'MCQ', TRUE),
(4, 'What is the purpose of the aria-label attribute in accessible HTML markup?', 'Accessibility', 'BEGINNER', 'A11y, Accessibility, ARIA', 'Applies custom CSS animations to the element', 'Provides an invisible, accessible text description for screen readers when visible text is absent', 'Defines a database column name', 'Translates text to another language automatically', 'B', 'aria-label defines an accessible string that labels an interactive element (e.g. icon-only button) for assistive technologies like screen readers.', 'MCQ', TRUE),
(4, 'What is the difference between null and undefined in JavaScript?', 'JavaScript', 'BEGINNER', 'null, undefined, Data Types', 'undefined represents uninitialized or missing value; null represents an intentional assignment of no value', 'null means the variable does not exist in memory; undefined is a valid number', 'They are identical and evaluate strictly equal (null === undefined)', 'null is a boolean type in JavaScript', 'A', 'undefined indicates that a variable has been declared but not assigned a value; null is an intentional assignment representing an empty object reference.', 'MCQ', TRUE),
(4, 'In React, what is prop drilling and how is it commonly solved?', 'React Architecture', 'INTERMEDIATE', 'Prop Drilling, Context API, State Management', 'Compiling code into web workers', 'Passing props through deeply nested intermediate components that do not need them; solved using Context API or Zustand', 'Drilling holes in CSS styling', 'A method of connecting to a MySQL database from React', 'B', 'Prop drilling occurs when data is passed through multiple intermediate levels; it is mitigated by Context API or external state stores.', 'MCQ', TRUE),
(4, 'What is the difference between Event Bubbling and Event Capturing in the DOM?', 'DOM Internals', 'INTERMEDIATE', 'Event Bubbling, Event Capturing, DOM', 'Bubbling propagates upward from the target to the root; capturing propagates downward from the root to the target', 'Bubbling only occurs for mouse clicks; capturing occurs for keyboard events', 'They are synonymous terms for the same propagation direction', 'Capturing happens only inside iframes', 'A', 'During the capture phase, events travel down the DOM tree to the target; during the bubble phase, events propagate upward from target to root.', 'MCQ', TRUE),
(4, 'What does the TypeScript Partial<T> utility type do?', 'TypeScript', 'INTERMEDIATE', 'TypeScript, Utility Types, Partial', 'Constructs a type with all properties of T set to optional', 'Constructs a type with all properties of T set to readonly', 'Removes all string properties from T', 'Picks only the first property of T', 'A', 'Partial<T> returns a new type where every property of T is marked as optional (value?: type).', 'MCQ', TRUE);
INSERT INTO questions (job_role_id, question_text, category, difficulty, expected_topics, option_a, option_b, option_c, option_d, correct_option, explanation, question_type, active) VALUES
(5, 'What is the primary trade-off between monolithic architecture and microservices?', 'System Architecture', 'INTERMEDIATE', 'Microservices, Monolith, Trade-offs', 'Microservices eliminate the need for network calls; monoliths require extensive network calls', 'Monoliths are simpler to develop and deploy initially; microservices provide independent scalability but introduce distributed system complexity', 'Microservices require all code to be written in a single language', 'Monoliths cannot connect to relational databases', 'B', 'Microservices decouple deployments and scale independently, but introduce network latency, distributed transactions, and operational complexity.', 'MCQ', TRUE),
(5, 'What is the Cache-Aside pattern (Lazy Loading) in backend caching?', 'Caching', 'INTERMEDIATE', 'Caching, Cache-Aside, Redis', 'The backend always queries the database and ignores the cache', 'The application first checks the cache; on a miss, it reads from the database and populates the cache for future requests', 'The database writes directly to the cache asynchronously', 'The cache periodically purges all records every second', 'B', 'In Cache-Aside, the application inspects the cache first; if data is missing, it reads from the storage layer and updates the cache.', 'MCQ', TRUE),
(5, 'What problem does the Circuit Breaker pattern solve in distributed backend systems?', 'Resilience', 'ADVANCED', 'Circuit Breaker, Resilience, Fault Tolerance', 'It prevents unauthorized users from calling internal endpoints', 'It prevents cascading failures by failing fast when a downstream dependency is unhealthy, giving it time to recover', 'It accelerates database queries by 10x', 'It automatically compresses large JSON payloads', 'B', 'A Circuit Breaker trips open when a remote service fails repeatedly, preventing resource exhaustion and cascading failures.', 'MCQ', TRUE),
(5, 'What is the purpose of database horizontal partitioning (sharding)?', 'Database Architecture', 'ADVANCED', 'Sharding, Partitioning, Scalability', 'Adding more RAM to a single database server', 'Distributing table rows across multiple independent database servers based on a shard key', 'Converting rows into columns for analytics', 'Creating secondary B-Tree indexes', 'B', 'Sharding distributes data horizontally across multiple database nodes to overcome single-node storage and throughput limits.', 'MCQ', TRUE),
(5, 'In REST API security, what is the purpose of rate limiting?', 'Security', 'BEGINNER', 'Rate Limiting, Security, DDoS', 'To limit the number of columns returned in a SQL query', 'To restrict the number of requests a client can make within a specified time window to prevent abuse and denial-of-service', 'To slow down server response times deliberately', 'To enforce password expiration policies', 'B', 'Rate limiting controls incoming traffic rates, protecting services from brute-force attacks, scraping, and denial-of-service.', 'MCQ', TRUE),
(5, 'What does the CAP Theorem state about distributed data stores?', 'Distributed Systems', 'ADVANCED', 'CAP Theorem, Consistency, Availability, Partition Tolerance', 'A distributed system can guarantee all three: Consistency, Availability, and Partition Tolerance simultaneously', 'In the presence of a network partition, a distributed system can guarantee either Consistency OR Availability, but not both', 'Databases can only store Consistency data', 'Partition tolerance is optional in distributed networks', 'B', 'The CAP Theorem proves that when network partitions (P) occur, a distributed system must choose between Consistency (C) and Availability (A).', 'MCQ', TRUE),
(5, 'What is a message broker (e.g., Apache Kafka or RabbitMQ) primarily used for in backend engineering?', 'Asynchronous Architecture', 'INTERMEDIATE', 'Message Broker, Kafka, RabbitMQ', 'To render HTML templates on the server', 'To decouple service-to-service communication via asynchronous message queues and event streams', 'To store relational tabular data permanently', 'To validate SSL certificates', 'B', 'Message brokers decouple microservices, buffer workloads, and enable asynchronous event-driven communication and pub/sub streaming.', 'MCQ', TRUE),
(5, 'What is the difference between horizontal scaling and vertical scaling?', 'System Architecture', 'BEGINNER', 'Scaling, Infrastructure', 'Vertical scaling adds more machines; horizontal scaling upgrades CPU/RAM of a single machine', 'Horizontal scaling adds more machine instances to the pool; vertical scaling adds CPU/RAM/disk to an existing single machine', 'Horizontal scaling is only possible with NoSQL databases', 'Vertical scaling is free of cost', 'B', 'Vertical scaling (scaling up) increases the capacity of a single server; horizontal scaling (scaling out) distributes load across multiple servers.', 'MCQ', TRUE),
(5, 'In database transactions, what is a dirty read?', 'Databases', 'INTERMEDIATE', 'Isolation Levels, Dirty Read, ACID', 'A query reading uncommitted data modified by another concurrent transaction', 'A query reading from a corrupt hard drive', 'A query containing syntax errors', 'Reading data that has been cached for more than 24 hours', 'A', 'A dirty read occurs at the Read Uncommitted isolation level when a transaction reads data that another transaction has modified but not yet committed.', 'MCQ', TRUE),
(5, 'Which database transaction isolation level prevents dirty reads, non-repeatable reads, and phantom reads completely?', 'Databases', 'ADVANCED', 'Isolation Levels, Serializable, ACID', 'Read Uncommitted', 'Read Committed', 'Repeatable Read', 'Serializable', 'D', 'Serializable is the highest isolation level; it completely isolates transactions from one another as if executed sequentially.', 'MCQ', TRUE),
(5, 'What is the purpose of an API Gateway in microservices architecture?', 'Architecture', 'INTERMEDIATE', 'API Gateway, Routing, Microservices', 'To compile backend source code into Docker images', 'To act as a single entry point handling routing, authentication, rate limiting, and SSL termination for internal services', 'To store SQL database tables in memory', 'To manage candidate resumes', 'B', 'An API Gateway provides a unified client entry point, decoupling clients from internal service topology and centralizing cross-cutting concerns.', 'MCQ', TRUE),
(5, 'What is the difference between optimistic locking and pessimistic locking?', 'Concurrency & DB', 'INTERMEDIATE', 'Locking, Optimistic vs Pessimistic', 'Optimistic locking assumes conflicts are rare and verifies a version number before commit; pessimistic locking locks records at the database level', 'Optimistic locking uses physical row locks; pessimistic locking does not lock rows', 'Pessimistic locking is only supported by NoSQL databases', 'Optimistic locking causes deadlocks on every query', 'A', 'Optimistic locking checks version fields at commit time to detect collisions; pessimistic locking acquires database row-level locks (e.g. SELECT FOR UPDATE).', 'MCQ', TRUE),
(5, 'What is the role of a dead letter queue (DLQ) in message-driven systems?', 'Message Queues', 'INTERMEDIATE', 'Dead Letter Queue, DLQ, Messaging', 'To delete messages that are more than 1 minute old', 'To isolate and store messages that cannot be processed successfully after maximum retry attempts for inspection', 'To speed up message delivery by 50%', 'To encrypt message bodies with RSA keys', 'B', 'A DLQ holds failed messages after retries are exhausted, preventing message loss and unblocking the main processing consumer queue.', 'MCQ', TRUE),
(5, 'What is the difference between symmetric and asymmetric encryption?', 'Security & Cryptography', 'BEGINNER', 'Encryption, Symmetric, Asymmetric', 'Symmetric uses one shared secret key for both encryption and decryption; asymmetric uses a public/private key pair', 'Symmetric uses two keys; asymmetric uses one key', 'Asymmetric encryption is 1000x faster than symmetric encryption', 'Symmetric encryption can only encrypt plain numbers', 'A', 'Symmetric encryption (e.g. AES) uses the same secret key for both operations; asymmetric encryption (e.g. RSA) uses public and private key pairs.', 'MCQ', TRUE),
(5, 'What is the purpose of database read replicas in high-traffic applications?', 'Database Architecture', 'BEGINNER', 'Read Replicas, Scaling, Databases', 'To replace the primary database permanently', 'To handle read-heavy traffic and offload SELECT queries from the primary read/write database node', 'To run automated schema migrations in parallel', 'To encrypt database credentials', 'B', 'Read replicas asynchronously replicate data from the primary node, allowing distributed read queries to scale horizontally.', 'MCQ', TRUE),
(5, 'What HTTP response status code should be returned when a client makes too many requests exceeding rate limits?', 'REST API', 'BEGINNER', 'HTTP 429, Rate Limiting', '400 Bad Request', '403 Forbidden', '429 Too Many Requests', '503 Service Unavailable', 'C', 'HTTP 429 Too Many Requests indicates the user has sent too many requests in a given amount of time (rate limit exceeded).', 'MCQ', TRUE),
(5, 'What is the Outbox Pattern in microservices data consistency?', 'Distributed Patterns', 'ADVANCED', 'Outbox Pattern, Event Driven, Microservices', 'Sending emails directly from the database server', 'Writing domain events to a database outbox table within the same transaction as business data, then publishing them via a relay', 'Storing expired JWT tokens in a file', 'Purging old records from the database automatically', 'B', 'The Transactional Outbox pattern ensures dual-write consistency by persisting domain state and message events within a single database transaction.', 'MCQ', TRUE),
(5, 'What is the purpose of hashing passwords with BCrypt or Argon2 rather than SHA-256?', 'Security', 'INTERMEDIATE', 'Password Hashing, BCrypt, Security', 'SHA-256 is too slow for web servers', 'BCrypt and Argon2 incorporate automatic salting and configurable computational work factors to resist GPU brute-force attacks', 'BCrypt passwords can be decrypted by server administrators', 'Argon2 produces a shorter hash string', 'B', 'General cryptographic hash functions like SHA-256 are too fast and vulnerable to GPU cracking; BCrypt/Argon2 are intentionally slow and salted.', 'MCQ', TRUE),
(5, 'In system design, what does the term throughput mean?', 'Performance', 'BEGINNER', 'Throughput, Metrics, Latency', 'The time taken to process a single request from start to finish', 'The number of units of work (e.g., requests, transactions) processed by a system within a given time period', 'The maximum amount of disk storage available', 'The number of bugs in a software codebase', 'B', 'Throughput measures the rate of successful work handled by a system (e.g. requests per second, RPS), whereas latency measures response time.', 'MCQ', TRUE),
(5, 'What is the role of an ORM (Object-Relational Mapping) framework?', 'Databases & ORM', 'BEGINNER', 'ORM, Hibernate, JPA', 'To convert relational database tables into object-oriented models in application memory and automate query generation', 'To design frontend user interfaces from database schemas', 'To encrypt database network packets', 'To replace SQL databases with Excel files', 'A', 'An ORM maps between relational database tables and object-oriented programming entities, automating SQL generation and result mapping.', 'MCQ', TRUE),
(5, 'What is a distributed trace (e.g., OpenTelemetry / Zipkin) used for in backend systems?', 'Observability', 'INTERMEDIATE', 'Distributed Tracing, OpenTelemetry', 'To record git commits across repositories', 'To track the path and latency of an HTTP request as it flows across multiple microservices and databases', 'To compile microservices into binary executables', 'To backup databases to cloud storage', 'B', 'Distributed tracing assigns a unique correlation/trace ID to an incoming request, recording timing and spans across all downstream services.', 'MCQ', TRUE);
INSERT INTO questions (job_role_id, question_text, category, difficulty, expected_topics, option_a, option_b, option_c, option_d, correct_option, explanation, question_type, active) VALUES
(6, 'In MySQL InnoDB, what is the default primary key index structure?', 'Indexing Internals', 'INTERMEDIATE', 'Clustered Index, B+ Tree, InnoDB', 'Hash Index', 'Clustered B+ Tree Index', 'LSM Tree Index', 'Bitmap Index', 'B', 'InnoDB organizes table data in a Clustered Index ordered by the primary key, storing the actual table rows directly in the B+ Tree leaf pages.', 'MCQ', TRUE),
(6, 'What is the difference between a clustered index and a secondary (non-clustered) index in InnoDB?', 'Indexing', 'INTERMEDIATE', 'Clustered Index, Secondary Index, InnoDB', 'A secondary index leaf node contains the primary key value; a clustered index leaf node contains the complete row data', 'A clustered index is stored in memory only; secondary indexes are on disk', 'A table can have multiple clustered indexes', 'Secondary indexes do not use B+ Trees', 'A', 'In InnoDB, the clustered index leaf stores the entire row; secondary index leaf nodes store only the indexed column and the primary key reference.', 'MCQ', TRUE),
(6, 'What is a covering index in SQL query optimization?', 'Query Optimization', 'INTERMEDIATE', 'Covering Index, EXPLAIN, Performance', 'An index that covers all tables in a database schema', 'An index that contains all the columns requested by a query, allowing the engine to satisfy the query entirely from the index without table lookup', 'An index that automatically encrypts table data', 'An index created on every column of a table', 'B', 'A covering index includes all columns referenced in the SELECT, WHERE, and JOIN clauses, eliminating expensive bookmark row lookups.', 'MCQ', TRUE),
(6, 'What does EXPLAIN output type "ALL" indicate in MySQL query execution plans?', 'Query Optimization', 'BEGINNER', 'EXPLAIN, Table Scan, Performance', 'The query utilizes all available indexes efficiently', 'A full table scan: the storage engine must examine every row in the table', 'All rows returned match the query conditions', 'The query executed in under 1 millisecond', 'B', 'type: ALL in an EXPLAIN execution plan indicates a full table scan, which is typically the slowest access method and indicates missing indexes.', 'MCQ', TRUE),
(6, 'What is the difference between WHERE and HAVING clauses in SQL?', 'SQL Syntax', 'BEGINNER', 'WHERE, HAVING, Aggregate Functions', 'WHERE filters individual rows before aggregation; HAVING filters groups after GROUP BY aggregation', 'HAVING can only be used with numbers; WHERE is used with strings', 'They are completely interchangeable', 'WHERE is only valid in subqueries', 'A', 'WHERE filters individual records before aggregation; HAVING filters summarized groups formed by GROUP BY operations.', 'MCQ', TRUE),
(6, 'What is a SQL database deadlock?', 'Concurrency & Locking', 'ADVANCED', 'Deadlock, Locking, Transactions', 'A database server that runs out of memory and crashes', 'A situation where two or more transactions hold locks that the other transactions need, creating a circular wait cycle', 'A query that takes longer than 60 seconds to finish', 'A table with no primary key defined', 'B', 'A deadlock occurs when two transactions mutually hold locks that the other requires to continue, preventing either from progressing.', 'MCQ', TRUE),
(6, 'How does MySQL InnoDB automatically resolve deadlocks when they occur?', 'Concurrency & Locking', 'ADVANCED', 'Deadlock Detection, Rollback, InnoDB', 'It crashes the database service immediately', 'It detects the circular wait in the lock graph and rolls back the transaction that modified the fewest rows', 'It pauses all queries for 1 hour', 'It forces both transactions to commit simultaneously', 'B', 'InnoDB deadlock detection identifies cycles in the lock wait-for graph and rolls back the smaller transaction (the one with the fewest undo records).', 'MCQ', TRUE),
(6, 'What is the difference between UNION and UNION ALL in SQL?', 'SQL Syntax', 'BEGINNER', 'UNION, UNION ALL, Set Operations', 'UNION combines results and removes duplicate rows; UNION ALL combines results and retains all duplicates', 'UNION ALL removes duplicates; UNION keeps duplicates', 'UNION only works on tables with identical column names', 'UNION ALL is 10x slower than UNION', 'A', 'UNION performs an implicit sorting/deduplication step to remove duplicates; UNION ALL simply appends results, making it much faster.', 'MCQ', TRUE),
(6, 'What does the SQL command TRUNCATE TABLE do compared to DELETE FROM table?', 'SQL DDL vs DML', 'BEGINNER', 'TRUNCATE, DELETE, DDL, DML', 'TRUNCATE is a DDL operation that drops and re-creates the table data pages quickly without row-by-row logging; DELETE is DML and logs each row', 'TRUNCATE only deletes the last 10 rows', 'DELETE is 100x faster than TRUNCATE', 'TRUNCATE can be filtered with a WHERE clause', 'A', 'TRUNCATE is a DDL operation that deallocates data pages rapidly and resets auto-increment counters; DELETE scans and logs each row individually.', 'MCQ', TRUE),
(6, 'In relational database normalization, what condition defines Third Normal Form (3NF)?', 'Normalization', 'INTERMEDIATE', 'Normalization, 3NF, Transitive Dependency', 'Table has no duplicate column names', 'Table is in 2NF and has no transitive dependencies (non-key attributes depend only on the primary key)', 'Table has no foreign keys', 'Table contains fewer than 10 columns', 'B', '3NF requires that the table is in 2NF and every non-prime attribute is non-transitively dependent on every candidate key.', 'MCQ', TRUE),
(6, 'What is the purpose of the Write-Ahead Logging (WAL) / Redo Log in relational databases?', 'Database Internals', 'ADVANCED', 'WAL, Redo Log, Durability, ACID', 'To log user passwords for auditing', 'To ensure Durability (ACID) by recording changes to log files on disk before dirty pages are written to data files', 'To compress query output sent to clients', 'To generate daily PDF reports', 'B', 'WAL ensures durability and crash recovery: transaction changes are written sequentially to the redo log before dirty buffers are flushed to data pages.', 'MCQ', TRUE),
(6, 'What is the difference between an INNER JOIN and a LEFT OUTER JOIN?', 'SQL Joins', 'BEGINNER', 'Joins, INNER JOIN, LEFT JOIN', 'INNER JOIN returns matching rows from both tables; LEFT JOIN returns all rows from the left table and matched rows from the right table (with NULLs for unmatched)', 'LEFT JOIN returns only rows that have NULL values', 'INNER JOIN is only used for primary keys', 'There is no difference in result set', 'A', 'INNER JOIN includes only records with matches in both tables; LEFT JOIN preserves all left-table rows, padding missing right-table columns with NULL.', 'MCQ', TRUE),
(6, 'What is the difference between CHAR and VARCHAR data types in MySQL?', 'Data Types', 'BEGINNER', 'CHAR, VARCHAR, Storage', 'CHAR is fixed-length and right-padded with spaces; VARCHAR is variable-length and stores actual length plus prefix byte', 'VARCHAR is always fixed-length; CHAR is variable', 'CHAR can store up to 4GB of text; VARCHAR cannot', 'They allocate the exact same disk storage for any string', 'A', 'CHAR(N) always allocates fixed N characters, padding shorter strings with spaces; VARCHAR(N) stores only the characters entered plus 1 or 2 length bytes.', 'MCQ', TRUE),
(6, 'In MySQL, what is a composite (multi-column) index and the Leftmost Prefix Rule?', 'Indexing', 'INTERMEDIATE', 'Composite Index, Leftmost Prefix, MySQL', 'An index can only be used by queries if the query conditions include the leftmost columns of the composite index in order', 'The index is only used if all columns in the table are specified', 'Composite indexes can only be queried from right to left', 'The rule dictates that indexes must only be created on left-aligned tables', 'A', 'Under the Leftmost Prefix Rule, a composite index on (A, B, C) can satisfy queries filtering on (A), (A, B), or (A, B, C), but cannot be used for (B) or (C) alone.', 'MCQ', TRUE),
(6, 'What is a SQL Window Function (e.g. ROW_NUMBER(), RANK(), DENSE_RANK())?', 'SQL Analytics', 'INTERMEDIATE', 'Window Functions, OVER, Partition By', 'A function that only executes inside GUI windows', 'A function that performs calculations across a set of table rows related to the current row without collapsing rows into a single output row', 'A function that permanently modifies table indexes', 'A query that runs on Microsoft Windows servers only', 'B', 'Window functions compute aggregate-like calculations over partitions of rows defined by the OVER() clause while preserving individual row identity.', 'MCQ', TRUE),
(6, 'What is the difference between RANK() and DENSE_RANK() in SQL window functions?', 'SQL Analytics', 'INTERMEDIATE', 'RANK, DENSE_RANK, Window Functions', 'RANK() skips rank numbers after duplicate values; DENSE_RANK() assigns consecutive rank numbers without gaps', 'DENSE_RANK() skips rank numbers; RANK() does not', 'RANK() can only be used on string columns', 'DENSE_RANK() deletes tie values', 'A', 'If two rows tie for 1st place, RANK() assigns ranks 1, 1, 3 (skipping 2); DENSE_RANK() assigns ranks 1, 1, 2 (no gaps in ranking).', 'MCQ', TRUE),
(6, 'What is a database view, and how does a Materialized View differ from a standard View?', 'Database Views', 'INTERMEDIATE', 'Views, Materialized Views', 'A standard view is a saved virtual query executed dynamically; a materialized view physically stores the query result on disk and can be refreshed', 'A standard view stores data on disk; a materialized view does not', 'Views cannot be queried with SELECT statements', 'Materialized views cannot be indexed', 'A', 'Standard views compute results dynamically on each query; materialized views store the precomputed result set physically on disk.', 'MCQ', TRUE),
(6, 'What is a foreign key constraint and what does ON DELETE CASCADE specify?', 'Foreign Keys', 'BEGINNER', 'Foreign Key, ON DELETE CASCADE, Constraints', 'It encrypts the child table when the parent is deleted', 'When a row in the parent table is deleted, all matching referenced rows in the child table are automatically deleted as well', 'It prevents any row from ever being deleted from the parent table', 'It deletes the entire database schema', 'B', 'ON DELETE CASCADE automatically removes associated child records when the referenced parent primary key row is deleted.', 'MCQ', TRUE),
(6, 'What does the SQL command COALESCE(val1, val2, val3) return?', 'SQL Functions', 'BEGINNER', 'COALESCE, NULL Handling', 'The first non-NULL expression from the argument list', 'The mathematical average of all non-null values', 'A boolean true if all arguments are null', 'The total number of arguments passed', 'A', 'COALESCE evaluates arguments in sequence and returns the current value of the first expression that does not evaluate to NULL.', 'MCQ', TRUE),
(6, 'What is the purpose of database Connection Pooling timeout configurations?', 'Database Tuning', 'INTERMEDIATE', 'Connection Pool, Timeout, HikariCP', 'To delete slow database users after 5 minutes', 'To prevent application threads from hanging indefinitely waiting for an available connection from an exhausted pool', 'To shut down the MySQL service every night', 'To enforce SSL handshake rotation', 'B', 'Setting connection acquisition timeouts prevents caller threads from waiting forever when the pool is starved under heavy traffic.', 'MCQ', TRUE),
(6, 'What is a phantom read in relational database transactions?', 'Isolation Levels', 'ADVANCED', 'Phantom Read, Isolation Levels, Transactions', 'A query reading data that never existed on disk', 'A transaction executing a range query twice and finding newly inserted/committed rows on the second read that were not present on the first read', 'A query returning data from deleted accounts', 'A corrupted database index page', 'B', 'A phantom read occurs when another transaction inserts new rows matching a range query filter between a transaction two reads.', 'MCQ', TRUE);
