-- V3__mcq_support.sql
-- Add Multiple Choice Question (MCQ) support and seed comprehensive 120+ MCQ question bank

-- 1. Alter schema for questions
ALTER TABLE questions
    ADD COLUMN option_a TEXT NULL,
    ADD COLUMN option_b TEXT NULL,
    ADD COLUMN option_c TEXT NULL,
    ADD COLUMN option_d TEXT NULL,
    ADD COLUMN correct_option VARCHAR(10) NULL,
    ADD COLUMN explanation TEXT NULL,
    ADD COLUMN question_type VARCHAR(20) NOT NULL DEFAULT 'THEORETICAL';

-- 2. Alter schema for interview_questions snapshot
ALTER TABLE interview_questions
    ADD COLUMN option_a TEXT NULL,
    ADD COLUMN option_b TEXT NULL,
    ADD COLUMN option_c TEXT NULL,
    ADD COLUMN option_d TEXT NULL,
    ADD COLUMN correct_option VARCHAR(10) NULL,
    ADD COLUMN explanation TEXT NULL,
    ADD COLUMN question_type VARCHAR(20) NOT NULL DEFAULT 'THEORETICAL',
    ADD COLUMN marked_for_review BOOLEAN NOT NULL DEFAULT FALSE;

-- 3. Alter schema for answers
ALTER TABLE answers
    ADD COLUMN selected_option VARCHAR(10) NULL,
    ADD COLUMN is_correct BOOLEAN NULL,
    MODIFY COLUMN answer_text MEDIUMTEXT NULL;

-- 4. Alter schema for interview_reports
ALTER TABLE interview_reports
    ADD COLUMN total_questions_count INT NULL,
    ADD COLUMN correct_answers_count INT NULL,
    ADD COLUMN incorrect_answers_count INT NULL,
    ADD COLUMN unanswered_count INT NULL;

